cd /tmp/gol && D=/private/var/folders/9t/wb1rb8796x9dx_7n376r8x300000gq/T/miri-field/r2/06-gpu-life/miri-skill/claude-opus/2
cat > ref.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
int main(int c,char**v){FILE*f=fopen(v[1],"r");int w,h,g;fscanf(f,"%d %d %d",&w,&h,&g);
int*a=calloc(w*h,4),*b=calloc(w*h,4);for(int i=0;i<w*h;i++)fscanf(f,"%d",&a[i]);
while(g--){for(int y=0;y<h;y++)for(int x=0;x<w;x++){int s=0;for(int dy=-1;dy<=1;dy++)for(int dx=-1;dx<=1;dx++){if(!dx&&!dy)continue;int X=x+dx,Y=y+dy;if(X>=0&&X<w&&Y>=0&&Y<h)s+=a[Y*w+X];}
b[y*w+x]=(s==3||(s==2&&a[y*w+x]));}int*t=a;a=b;b=t;}
long n=0;for(int y=0;y<h;y++){for(int x=0;x<w;x++){printf(x?" %d":"%d",a[y*w+x]);n+=a[y*w+x];}printf("\n");}printf("ALIVE %ld\n",n);}
EOF
cc -O2 -o ref ref.c && ./ref huge.txt > exp.txt && miri run $D/main.mi -- huge.txt > got.txt && cmp exp.txt got.txt && echo match1000
python3 gen.py 300 511 999 3 > h2.txt; ./ref h2.txt > exp.txt; miri run $D/main.mi -- h2.txt > got.txt; cmp exp.txt got.txt && echo match2

